fn noise(i: i32, salt: i32, amp: i32) -> i32 {
    let mut hsh: i32 = i * 2654435761 + salt;
    hsh = hsh * 1103515245 + 12345;
    ((hsh >> 16) & 32767) % amp
}

fn frame(t: i32) {
    let w: i32 = host::display::width();
    let h: i32 = host::display::height();
    host::display::clear(0x0d1026);
    let mut x: i32 = 0;
    while x < w {
        let wf: i32 = x + t / 8;
        let sf: i32 = 64;
        let i0: i32 = wf / sf;
        let f0: i32 = wf % sf;
        let a0: i32 = noise(i0, 11, 100);
        let a1: i32 = noise(i0 + 1, 11, 100);
        let hf: i32 = 90 + a0 + (a1 - a0) * f0 / sf;
        host::display::fill_rect(x, h - hf, 4, hf, 0x2e3a5c);
        let wn: i32 = x + t / 3;
        let sn: i32 = 48;
        let i1: i32 = wn / sn;
        let f1: i32 = wn % sn;
        let b0: i32 = noise(i1, 99, 80);
        let b1: i32 = noise(i1 + 1, 99, 80);
        let hn: i32 = 30 + b0 + (b1 - b0) * f1 / sn;
        host::display::fill_rect(x, h - hn, 4, hn, 0x101728);
        x = x + 4;
    }
    host::display::present();
}
